            "signature": signature
        }

        if amount:
            payload["amount"] = amount

        if metadata:
            payload["metadata"] = metadata

        try:
            # Make the API request
            response = self.session.post(
                f"{self.base_url}/claim",
                data=json.dumps(payload),
