    public static function calculateTrend(array $data): string
    {
        if (count($data) < 2) {
            return 'Insufficient data';
        }

        $first = reset($data)['value'];
        $last = end($data)['value'];

        if ($last > $first) {
            return 'Increasing';
        } elseif ($last < $first) {
            return 'Decreasing';
        } else {
            return 'Stable';
        }
    }
