// const price = await getCryptoPrice('BTC', { apiKey: 'your-api-key' });
// const prices = await getMultipleCryptoPrices(['BTC', 'ETH', 'LTC'], { apiKey: 'your-api-key' });

module.exports = {
    getCryptoPrices,
    getCryptoPrice,
    getMultipleCryptoPrices
};
